'use strict';
const $=id=>document.getElementById(id),full=document.body.classList.contains('full-dashboard');
const TYPES={commitment:'Commitment',refund:'Refund',payment:'Payment',interview:'Interview',deadline:'Deadline',response:'Reply',document:'Document',meeting:'Meeting',followup:'Follow-up'};
const STYLES={professional:'Professional',friendly:'Friendly',formal:'Formal',short:'Short & Direct',detailed:'Detailed',persuasive:'Persuasive',apologetic:'Apologetic',followup:'Follow-up',negotiation:'Negotiation',interview:'Interview Response'};
const today=()=>{const d=new Date();return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const id=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
function withLocalProfileSignature(text){const context=((emailContext?.subject||'')+' '+(emailContext?.text||'')).toLowerCase();return InboxActionProfile.ensureProfileSignature(text,currentProfile,/job|position|career|recruit|application|analyst|developer|interview|hiring|resume/.test(context));}
function validReplyCandidate(text){return InboxActionProfile.validateAIDraft(text,emailContext,currentProfile);}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let suggestions=[],classification={},page='dashboard',taskView='pending',reminderView='all',editingId=null,tone='professional',emailContext=null,currentProfile=InboxActionProfile.normalizeProfile(null),inboxEmails=[],currentGmailMode='unknown',gmailModeBusy=false,analysisBusy=false,analysisReplyVariant=0;
function status(text,error=false){$('statusBanner').textContent=text;$('statusBanner').classList.toggle('error',error);$('statusBanner').hidden=!text;}
function replyStatus(text,type=''){$('replyState').textContent=text;$('replyState').className=`reply-state ${type}`;}
function dueState(t){return !t.dueDate||t.completed?'none':t.dueDate<today()?'overdue':t.dueDate===today()?'today':'future';}
function snoozed(t){return !!t.snoozedUntil&&t.snoozedUntil>today();}
function dateLabel(value){if(!value)return'';const d=new Date(`${value}T12:00:00`);return Number.isNaN(+d)?value:new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(d);}
function ago(value){if(!value)return'Recently';const m=Math.floor((Date.now()-new Date(value))/60000);return m<1?'Just now':m<60?`${m}m ago`:m<1440?`${Math.floor(m/60)}h ago`:`${Math.floor(m/1440)}d ago`;}
async function tasksGet(){const d=await chrome.storage.local.get({tasks:[]});return Array.isArray(d.tasks)?d.tasks:[];}
async function tasksSet(value){await chrome.storage.local.set({tasks:value});}
async function prefsGet(){const d=await chrome.storage.local.get({preferences:{}});return{defaultTone:'professional',backendEndpoint:'',externalAIConsent:false,externalProfileConsent:false,inboxAnalysisEnabled:true,prioritizeUnread:true,vipSenders:'',mutedSenders:'',inboxFeedback:{},...d.preferences};}
async function prefsSet(patch){const p=await prefsGet();Object.assign(p,patch);await chrome.storage.local.set({preferences:p});return p;}
function go(next){if(!$(`page-${next}`))return;page=next;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===`page-${next}`));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===next));$('pageTitle').textContent=({dashboard:'Dashboard',inbox:'Visible Inbox',career:'Career Tracker',tasks:'My Tasks','smart-reply':'AI Smart Reply',reminders:'Reminders',settings:'Settings',profile:'Personal Profile'})[next];status('');if(next==='tasks')renderTasks();if(next==='reminders')renderReminders();if(next==='smart-reply')renderContext();if(next==='inbox')loadInboxAnalysis();if(next==='career')renderApplications();if(next==='profile')renderProfile();}
function editForm(t){return `<form class="edit-form" data-id="${esc(t.id)}"><label>Task title<input name="title" required maxlength="180" value="${esc(t.title)}"></label><label>Description<textarea name="description" rows="3" maxlength="1000">${esc(t.description||'')}</textarea></label><div class="form-grid"><label>Sender<input name="sender" maxlength="180" value="${esc(t.sender||'')}"></label><label>Due date<input name="dueDate" type="date" value="${esc(t.dueDate||'')}"></label><label>Priority<select name="priority"><option value="low" ${t.priority==='low'?'selected':''}>Low</option><option value="normal" ${(!t.priority||t.priority==='normal')?'selected':''}>Normal</option><option value="high" ${t.priority==='high'?'selected':''}>High</option></select></label><label>Status<select name="completed"><option value="false" ${!t.completed?'selected':''}>Pending</option><option value="true" ${t.completed?'selected':''}>Completed</option></select></label></div><div class="form-actions"><button class="button button-primary" type="submit">Save changes</button><button class="button button-quiet cancel-edit" type="button">Cancel</button></div></form>`;}
function taskCard(t,from='tasks'){const due=dueState(t);return `<article class="task-card ${t.completed?'completed':''}"><input class="complete-check" type="checkbox" data-id="${esc(t.id)}" ${t.completed?'checked':''} aria-label="Mark ${esc(t.title)} complete"><div class="task-main"><p class="task-title">${esc(t.title)}</p><p class="task-description">${esc(t.description||'')}</p><div class="task-meta"><span class="type-tag">${esc(TYPES[t.type]||'Follow-up')}</span><span class="priority-tag ${t.priority==='high'?'high':t.priority==='low'?'low':''}">${esc((t.priority||'normal').toUpperCase())} PRIORITY</span>${t.dueDate?`<span class="due-tag ${due==='overdue'?'overdue':''}">${due==='overdue'?'Overdue · ':''}${esc(dateLabel(t.dueDate))}</span>`:''}${snoozed(t)?`<span class="status-tag snooze-badge">Snoozed to ${esc(dateLabel(t.snoozedUntil))}</span>`:''}<span class="status-tag">${t.completed?'Completed':t.direction==='sender'?'Waiting for sender':'Pending'}</span></div><p class="sender-line">${esc(t.sender||'Sender not identified')}${t.senderEmail?` · ${esc(t.senderEmail)}`:''}${t.why?` · ${esc(t.why)}`:''}</p>${t.nextAction?`<p class="sender-line">Next: ${esc(t.nextAction)}</p>`:''}</div><div class="task-actions">${t.conversationUrl?`<button class="icon-button open-conversation" data-id="${esc(t.id)}" aria-label="Open original Gmail conversation" title="Open conversation">?</button>`:''}<button class="icon-button edit-task" data-id="${esc(t.id)}" aria-label="Edit task" title="Edit">?</button>${!t.completed?`<button class="icon-button draft-task" data-id="${esc(t.id)}" aria-label="Create Gmail reply draft" title="Reply draft">?</button><button class="icon-button snooze-task" data-id="${esc(t.id)}" aria-label="${snoozed(t)?'Cancel snooze':'Snooze until tomorrow'}" title="${snoozed(t)?'Cancel snooze':'Snooze one day'}">${snoozed(t)?'?':'zz'}</button>`:''}${from==='reminders'&&t.dueDate?`<button class="icon-button clear-reminder" data-id="${esc(t.id)}" aria-label="Cancel reminder" title="Clear reminder">?</button>`:''}<button class="icon-button delete-task" data-id="${esc(t.id)}" aria-label="Delete task" title="Delete">×</button></div></article>${editingId===t.id?editForm(t):''}`;}
async function dashboardRender(){const list=await tasksGet(),pending=list.filter(t=>!t.completed),done=list.filter(t=>t.completed),over=pending.filter(t=>dueState(t)==='overdue'),limit=new Date(Date.now()+7*864e5).toISOString().slice(0,10),focus=pending.filter(t=>dueState(t)==='today'||t.priority==='high'&&!snoozed(t)).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')).slice(0,4),up=pending.filter(t=>t.dueDate>=today()&&t.dueDate<=limit&&!snoozed(t)).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,4);$('statPending').textContent=pending.length;$('statCompleted').textContent=done.length;$('statOverdue').textContent=over.length;$('navTaskCount').textContent=pending.length;$('navReminderCount').textContent=pending.filter(t=>['overdue','today'].includes(dueState(t))).length;$('todayList').innerHTML=focus.map(compactRow).join('');$('todayEmpty').hidden=focus.length>0;$('upcomingList').innerHTML=up.map(compactRow).join('');$('upcomingEmpty').hidden=up.length>0;const recent=[...list].sort((a,b)=>new Date(b.completedAt||b.createdAt||0)-new Date(a.completedAt||a.createdAt||0)).slice(0,5);$('recentActivity').innerHTML=recent.map(t=>`<div class="activity-row"><i class="activity-dot" style="background:${t.completed?'#56d9b3':'#a184ff'}"></i><span>${t.completed?'Completed':'Saved'} <strong>${esc(t.title)}</strong></span><span class="activity-time">${ago(t.completedAt||t.createdAt)}</span></div>`).join('');$('activityEmpty').hidden=recent.length>0;$('todayDate').textContent=new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date());$('pendingCount').textContent=pending.length;$('completedCount').textContent=done.length;$('allCount').textContent=list.length;}
function compactRow(t){return `<div class="compact-row"><i class="compact-mark ${dueState(t)==='overdue'?'overdue':''}"></i><div class="compact-row-copy"><strong>${esc(t.title)}</strong><small>${esc(t.sender||TYPES[t.type]||'Task')} · ${esc(TYPES[t.type]||'Follow-up')}</small></div><span class="compact-date">${esc(t.dueDate?dateLabel(t.dueDate):t.priority==='high'?'High priority':'')}</span></div>`;}
function filterTasks(list){const q=$('taskSearch').value.trim().toLowerCase(),type=$('taskTypeFilter').value,priority=$('taskPriorityFilter').value,direction=$('taskDirectionFilter').value;return list.filter(t=>taskView==='all'||(taskView==='completed'?t.completed:!t.completed)).filter(t=>type==='all'||t.type===type).filter(t=>priority==='all'||(t.priority||'normal')===priority).filter(t=>direction==='all'||(t.direction||'you')===direction).filter(t=>!q||[t.title,t.description,t.sender,t.senderEmail].some(v=>String(v||'').toLowerCase().includes(q))).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));}
async function renderTasks(){const all=await tasksGet();$('pendingCount').textContent=all.filter(t=>!t.completed).length;$('completedCount').textContent=all.filter(t=>t.completed).length;$('allCount').textContent=all.length;document.querySelectorAll('.task-tab').forEach(b=>b.classList.toggle('active',b.dataset.taskView===taskView));const shown=filterTasks(all);$('taskList').innerHTML=shown.map(t=>taskCard(t)).join('');$('taskEmpty').hidden=shown.length>0;$('taskEmptyTitle').textContent=all.length?'No matching tasks':'Nothing here yet';$('taskEmptyCopy').textContent=all.length?'Try another search or filter.':'Analyze an open Gmail message or add a task yourself.';}
function reminderFilter(all){const p=all.filter(t=>!t.completed&&t.dueDate&&!snoozed(t)),end=new Date(Date.now()+7*864e5).toISOString().slice(0,10);return p.filter(t=>reminderView==='all'||reminderView==='overdue'&&t.dueDate<today()||reminderView==='today'&&t.dueDate===today()||reminderView==='upcoming'&&t.dueDate>today()&&t.dueDate<=end).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));}
async function renderReminders(){const all=await tasksGet(),p=all.filter(t=>!t.completed&&t.dueDate&&!snoozed(t)),end=new Date(Date.now()+7*864e5).toISOString().slice(0,10);$('reminderOverdueCount').textContent=p.filter(t=>t.dueDate<today()).length;$('reminderTodayCount').textContent=p.filter(t=>t.dueDate===today()).length;$('reminderUpcomingCount').textContent=p.filter(t=>t.dueDate>today()&&t.dueDate<=end).length;document.querySelectorAll('.reminder-tab').forEach(b=>b.classList.toggle('active',b.dataset.reminderView===reminderView));const shown=reminderFilter(all);$('reminderList').innerHTML=shown.map(t=>taskCard(t,'reminders')).join('');$('reminderEmpty').hidden=shown.length>0;}
function makeEmailSummary(email,actions,classification){
 const body=String(email?.text||'').replace(/\r/g,'').split(/(?:^|\n)(?:On .{3,180} wrote:|[- ]{2,}Original Message[- ]{2,}|From:\s[^\n]+\nSent:\s[^\n]+)/i)[0].split('\n').filter(line=>!/^\s*>/.test(line)).join(' ').replace(/\s+/g,' ').trim();
 const sentences=body.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[],excerpt=sentences.map(x=>x.trim()).filter(Boolean).slice(0,3).join(' ');
 const intent=classification.career&&classification.career!=='informational'?INBOX_LABELS[classification.career]||classification.career:actions.length?`Action signals: ${[...new Set(actions.map(a=>TYPES[a.type]||a.type))].join(', ')}`:classification.promotional?'Promotional message':'Informational message';
 const datePattern=/\b(?:today|tomorrow|tonight|next week|next month|this week|this month|(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)(?:,?\s+(?:January|February|March|April|May|June|July|August|September|October|November|December)?\s*\d{0,2})?|(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2}(?:,?\s+\d{4})?|\d{4}-\d{2}-\d{2})\b/gi;
 const dates=[...body.matchAll(datePattern)].map(m=>m[0]);for(const action of actions)if(action.dueDate)dates.push(action.dueDate);
 return{excerpt:excerpt.slice(0,1000)||'The message body was extracted, but no readable sentence summary could be formed.',intent,dates:[...new Set(dates)].slice(0,12),replyRequired:actions.some(a=>a.direction==='you')||!!classification.requiresReply,actionCount:actions.length};
}
function renderEmailAnalysis(){const result=$('emailAnalysisResult'),email=emailContext;if(!result||!email?.text)return;const summary=classification.summary||makeEmailSummary(email,suggestions,classification);$('analysisSummary').textContent=summary.excerpt;$('analysisIntention').textContent=`Sender intention: ${summary.intent}. Sender: ${email.sender||email.senderEmail||'not identified'}${email.recipients?.length?` · Recipient(s): ${email.recipients.join(', ')}`:''}.`;$('analysisDates').textContent=`Dates/deadlines found in message text: ${summary.dates.length?summary.dates.join(' · '):'None detected'}. Required actions: ${suggestions.length? suggestions.map(a=>a.title).join('; '):'No explicit actionable commitment detected'}.`;$('emailReplyRequired').textContent=summary.replyRequired?'Reply appears to be required':'No explicit reply request detected';$('analysisReplyDraft').value=localProfessionalReply(email,summary);$('analysisReplyNote').textContent='Locally generated from the opened email text and relevant profile facts. Review the draft before using it; your profile is never included in backend requests.';result.hidden=false;}
function localProfessionalReply(email,summary){return InboxActionProfile.generateReplies(email,'professional',currentProfile)[0]?.text||'';}
function validateReplyAnalysis(analysis){if(!analysis||typeof analysis.senderIntent!=='string'||typeof analysis.expectedResponse!=='string'||typeof analysis.messageType!=='string'||!Array.isArray(analysis.responsibilities)||!Array.isArray(analysis.requiredSkills)||!Array.isArray(analysis.matchedProfileEvidence)||!Array.isArray(analysis.unsupportedRequirements))return false;const q=analysis.qualityChecks||{};return ['answersActualEmail','usesFullContext','profileFactsSupported','relevantAndPersonalized','naturalProfessionalTone','notRepetitive'].every(key=>q[key]===true);}
function renderReplyAnalysis(analysis,profileIncluded){const rows=['Intent: '+analysis.senderIntent,'Expected response: '+analysis.expectedResponse,'Message type: '+analysis.messageType];if(analysis.jobTitle)rows.push('Role: '+analysis.jobTitle);if(analysis.company)rows.push('Company: '+analysis.company);if(analysis.responsibilities.length)rows.push('Responsibilities: '+analysis.responsibilities.join('; '));if(analysis.requiredSkills.length)rows.push('Requirements: '+analysis.requiredSkills.join(', '));if(analysis.matchedProfileEvidence.length)rows.push('Relevant profile evidence: '+analysis.matchedProfileEvidence.join('; '));if(analysis.unsupportedRequirements.length)rows.push('Experience gaps to represent honestly: '+analysis.unsupportedRequirements.join('; '));rows.push(profileIncluded?'Professional profile was shared with the configured backend by your separate consent.':'Professional profile was not shared.');$('replyAnalysisMeta').textContent=rows.join(' | ');$('replyAnalysisMeta').hidden=false;}
async function requestAIReply(style,includeThreeSuggestions){if(!emailContext?.text)throw Error('Read the open Gmail email before requesting a reply.');const p=await prefsGet();if(!p.backendEndpoint||!p.externalAIConsent)throw Error('Configure the AI backend and email-content consent in Settings first.');const payload=InboxActionProfile.buildAIReplyPayload(emailContext,style,currentProfile,{includeProfile:p.externalProfileConsent===true,includeThreeSuggestions});const result=await remote('reply',payload);if(!validateReplyAnalysis(result.analysis))throw Error('The backend does not support reply schema v2 with context analysis and quality checks. Update the backend before using AI replies.');if(!Array.isArray(result.suggestions))throw Error('Backend response invalid: expected a suggestions array.');const items=result.suggestions.slice(0,includeThreeSuggestions?3:1).map(x=>({label:String(x.label||'AI reply').slice(0,60),text:withLocalProfileSignature(String(x.text||'').trim()).slice(0,5000)})).filter(x=>validReplyCandidate(x.text));if(!items.length)throw Error('AI reply failed local placeholder, salary and experience checks.');return{items,analysis:result.analysis,profileIncluded:p.externalProfileConsent===true};}
async function regenerateAnalysisReply(){const p=await prefsGet();if(p.backendEndpoint&&p.externalAIConsent){try{const result=await requestAIReply('professional',false);if(!result.items.length)throw Error('The configured AI backend returned no safe reply.');$('analysisReplyDraft').value=result.items[0].text;$('analysisReplyNote').textContent=result.profileIncluded?'AI-generated from the email, thread and consented professional profile. Review the reply before using it.':'AI-generated from the email and thread. Profile context was withheld; enable separate profile consent for profile-aware backend writing.';return;}catch(error){$('analysisReplyDraft').value=localProfessionalReply(emailContext,classification.summary||makeEmailSummary(emailContext,suggestions,classification));$('analysisReplyNote').textContent='AI reply unavailable: '+error.message+' Local profile-aware draft shown instead.';return;}}analysisReplyVariant++;$('analysisReplyDraft').value=localProfessionalReply(emailContext,classification.summary||makeEmailSummary(emailContext,suggestions,classification));$('analysisReplyNote').textContent='Generated locally from the opened email and relevant saved profile details. No profile or email was sent to a backend.';}
function renderSuggestions(){ $('reviewSection').hidden=false;$('suggestionCount').textContent=suggestions.length;$('emailContext').textContent=suggestions.emailContext||'';const c=classification,labels=[c.urgent?'Urgent':null,c.important?'Important':null,c.requiresReply?'Requires your reply':null,c.waitingForSomeone?'Waiting for sender':null,c.promotional?'Promotional':null,c.informational?'Informational':null].filter(Boolean);const career=classification.career?`${INBOX_LABELS[classification.career]||classification.career} (${Math.round((classification.careerConfidence||0)*100)}%): ${classification.careerWhy||''}`:'';const details=Object.entries(classification.jobDetails||{}).filter(([,value])=>value).map(([key,value])=>`${key}: ${value}`).join(' / ');$('classificationSummary').textContent=[labels.length?`Action signals: ${labels.join(' / ')}`:'No action classification.',career,details?`Available job details: ${details}`:''].filter(Boolean).join(' | ');$('suggestionList').innerHTML=suggestions.map((s,i)=>`<article class="task-card suggestion-card"><input class="suggestion-check" type="checkbox" data-index="${i}" checked aria-label="Select action"><div class="task-main"><p class="task-title">${esc(s.title)}</p><p class="task-description">${esc(s.description)}</p><div class="task-meta"><span class="type-tag">${esc(TYPES[s.type]||'Follow-up')}</span><span class="priority-tag ${s.priority==='high'?'high':''}">${esc((s.priority||'normal').toUpperCase())} PRIORITY</span>${s.direction==='sender'?'<span class="status-tag">Waiting for sender</span>':''}${s.dueDate?`<span class="due-tag">${esc(dateLabel(s.dueDate))}</span>`:''}</div><p class="sender-line">${esc(s.why||'')}</p></div></article>`).join('');$('saveTasksButton').disabled=!suggestions.length;}
async function targetTab(){let tab;if(full){const saved=await chrome.storage.session.get({targetTabId:null});if(!saved.targetTabId)throw Error('Open this dashboard from the extension while a Gmail tab is active to grant temporary access.');try{tab=await chrome.tabs.get(saved.targetTabId);}catch{throw Error('The Gmail tab is no longer available. Reopen this dashboard from Gmail.');}}else{[tab]=await chrome.tabs.query({active:true,currentWindow:true});}if(!tab?.id||!/^https:\/\/mail\.google\.com\//i.test(tab.url||''))throw Error('Open Gmail in the active tab to analyze its current view.');return tab;}
function renderGmailMode(mode){currentGmailMode=mode;const indicator=$('gmailViewIndicator'),emailButton=$('analyzeButton'),inboxButton=$('analyzeVisibleInbox');if(indicator){indicator.textContent=mode==='inbox'?'Inbox Mode':mode==='email'?'Email Mode':mode==='unavailable'?'Gmail unavailable':'Gmail view · detecting';indicator.classList.toggle('mode-inbox',mode==='inbox');indicator.classList.toggle('mode-email',mode==='email');}if(emailButton){emailButton.disabled=mode!=='email'||analysisBusy;emailButton.classList.toggle('mode-active',mode==='email');emailButton.setAttribute('aria-pressed',String(mode==='email'));}if(inboxButton){inboxButton.disabled=mode!=='inbox'||analysisBusy;inboxButton.classList.toggle('mode-active',mode==='inbox');inboxButton.setAttribute('aria-pressed',String(mode==='inbox'));}}
async function refreshGmailMode(){if(gmailModeBusy)return;gmailModeBusy=true;try{const tab=await targetTab();const probe=await chrome.scripting.executeScript({target:{tabId:tab.id},func:()=>window.inboxToActionReader?.version===7});if(!probe?.[0]?.result)await chrome.scripting.executeScript({target:{tabId:tab.id},files:['content.js']});const result=await chrome.scripting.executeScript({target:{tabId:tab.id},func:()=>window.inboxToActionReader?.detectGmailView?.()||{mode:'unknown'}});const mode=result?.[0]?.result?.mode;renderGmailMode(['inbox','email'].includes(mode)?mode:'unknown');}catch(error){renderGmailMode(/Gmail in the active tab|dashboard from the extension|Gmail tab is no longer/i.test(error.message)?'unavailable':'unknown');}finally{gmailModeBusy=false;}}
async function readEmail(){const tab=await targetTab();await chrome.scripting.executeScript({target:{tabId:tab.id},files:['content.js']});const results=await chrome.scripting.executeScript({target:{tabId:tab.id},func:async()=>await window.inboxToActionReader?.readCurrentEmail?.()||{error:'Gmail reader unavailable. Reload Gmail and retry.'}});const email=results?.[0]?.result;if(email?.error)throw Error(email.error);if(!email?.text)throw Error('No visible open email body was found. Open a message and retry.');emailContext=email;await chrome.storage.session.set({lastAnalyzedEmail:email,targetTabId:tab.id});return email;}
function originPattern(url){return`${new URL(url).origin}/*`;}
function hasPaymentCardNumber(value){const matches=String(value).match(/(?:\d[ -]?){13,19}/g)||[];return matches.some(raw=>{const digits=raw.replace(/\D/g,'');if(digits.length<13||digits.length>19)return false;let sum=0,alternate=false;for(let i=digits.length-1;i>=0;i--){let n=Number(digits[i]);if(alternate){n*=2;if(n>9)n-=9;}sum+=n;alternate=!alternate;}return sum%10===0;});}
function prepareExternalPayload(payload){const json=JSON.stringify(payload);if(/\b(?:otp|one[- ]time (?:password|code|passcode)|password|passcode|verification code|security code|bank account|routing number|social security|ssn)\b/i.test(json)||/\b\d{3}-\d{2}-\d{4}\b/.test(json)||hasPaymentCardNumber(json))throw Error('External AI was blocked because this email appears to contain a password, verification code, or sensitive financial identifier. Use local analysis instead.');const redact=value=>typeof value==='string'?value.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,'[EMAIL]').replace(/(?:\+?\d[\d(). -]{7,}\d)/g,'[PHONE]'):Array.isArray(value)?value.map(redact):value&&typeof value==='object'?Object.fromEntries(Object.entries(value).map(([key,item])=>[key,redact(item)])):value;return redact(JSON.parse(json));}
async function remote(path,payload){const p=await prefsGet();if(!p.backendEndpoint||!p.externalAIConsent)throw Error('Configure a backend and explicit consent in Settings first.');const endpoint=new URL(p.backendEndpoint);if(endpoint.protocol!=='https:'&&!(endpoint.protocol==='http:'&&['localhost','127.0.0.1'].includes(endpoint.hostname)))throw Error('Backend must use HTTPS (HTTP is allowed for localhost only).');if(!await chrome.permissions.contains({origins:[originPattern(endpoint.href)]}))throw Error('Backend origin permission missing. Reconnect it in Settings.');const session=await chrome.storage.session.get({backendAccessToken:''});if(!session.backendAccessToken)throw Error('Enter a short-lived backend access token in Settings. The AI provider key must remain on the server.');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),25000);try{const response=await fetch(`${endpoint.origin}/v1/${path}`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+session.backendAccessToken},credentials:'omit',cache:'no-store',body:JSON.stringify(prepareExternalPayload(payload)),signal:controller.signal});if(response.status===429)throw Error('AI backend rate limit reached. Try again later.');if(response.status===401||response.status===403)throw Error('Backend token was rejected or expired. Enter a current short-lived token in Settings.');if(!response.ok)throw Error(`AI backend returned HTTP ${response.status}.`);return await response.json();}catch(error){if(error.name==='AbortError')throw Error('AI backend timed out. Try again later.');throw error;}finally{clearTimeout(timeout);}}
function safeGmailUrl(value){try{const u=new URL(value);return u.origin==='https://mail.google.com'?u.href:'';}catch{return'';}}
function validateAction(item,email){const types=new Set(Object.keys(TYPES));if(!item||item.requiresAction!==true||!types.has(item.type)||typeof item.title!=='string'||typeof item.description!=='string')return null;return{...item,title:item.title.trim().slice(0,180),description:item.description.trim().slice(0,650),why:String(item.why||'').slice(0,300),nextAction:String(item.nextAction||'').slice(0,300),dueDate:/^\d{4}-\d{2}-\d{2}$/.test(item.dueDate||'')?item.dueDate:'',priority:['high','normal','low'].includes(item.priority)?item.priority:'normal',direction:item.direction==='sender'?'sender':'you',sender:email.sender||'',senderEmail:email.senderEmail||'',recipients:email.recipients||[],emailSubject:email.subject||'',threadId:email.threadId||'',messageId:email.messageId||'',conversationUrl:safeGmailUrl(email.conversationUrl),status:item.direction==='sender'?'waiting':'pending',source:item.description.slice(0,500)};}
async function analyze(){const email=await readEmail(),p=await prefsGet();if(p.backendEndpoint&&p.externalAIConsent){const result=await remote('analyze',{schemaVersion:1,email:{sender:email.sender,senderEmail:email.senderEmail,recipients:email.recipients,subject:email.subject,text:email.text,conversationContext:email.conversationContext,threadId:email.threadId,messageId:email.messageId}});if(!Array.isArray(result.actions))throw Error('Backend response invalid: expected actions array.');const career=await chrome.runtime.sendMessage({type:'CLASSIFY_VISIBLE_EMAIL',email:{sender:email.sender,senderEmail:email.senderEmail,subject:email.subject,snippet:email.text}});classification={...(result.classification||{}),career:career?.classification?.category||'informational',careerConfidence:career?.classification?.confidence||0,careerWhy:career?.classification?.why||'',jobDetails:career?.classification?.jobDetails||{}};return result.actions.map(a=>validateAction(a,email)).filter(Boolean);}const local=await chrome.runtime.sendMessage({type:'ANALYZE_EMAIL',email});if(!local?.ok)throw Error(local?.error||'Local analysis failed.');classification=local.classification||{};return local.actions||[];}
