async function createReplyInThread(draft,task=null){const tab=await targetTab();await chrome.scripting.executeScript({target:{tabId:tab.id},files:['content.js']});const res=await chrome.scripting.executeScript({target:{tabId:tab.id},func:d=>window.inboxToActionReader?.createReplyDraft?.(d)||{ok:false,error:'Gmail reply helper unavailable.'},args:[{threadId:task?.threadId||emailContext?.threadId||'',conversationUrl:task?.conversationUrl||emailContext?.conversationUrl||'',body:draft}]});const out=res?.[0]?.result;if(!out?.ok)throw Error(out?.error||'Gmail did not confirm a reply draft.');return out;}
