async function generateReplies(){if(!emailContext?.text){replyStatus('Read the open Gmail email first so the reply can use its context.','error');return;}$('replyAnalysisMeta').hidden=true;$('replyAnalysisMeta').textContent='';const p=await prefsGet();if(p.backendEndpoint&&p.externalAIConsent){replyStatus('Understanding the email and preparing an AI reply...');try{const result=await requestAIReply(tone,true);showReplyOptions(result.items);renderReplyAnalysis(result.analysis,result.profileIncluded);replyStatus(result.profileIncluded?'AI replies are ready. The backend received the email context and the minimized profile you separately allowed. Review and edit before use.':'AI replies are ready from email context. Your profile was not shared; the local profile remains available in Personal Profile. Review and edit before use.','success');return;}catch(error){const items=localReplies(tone);if(!items.length)throw error;showReplyOptions(items);replyStatus('AI generation unavailable: '+error.message+' Showing local profile-aware drafts instead.','error');return;}}const items=localReplies(tone);if(!items.length){replyStatus('The email body is unavailable. Read the current Gmail message first; no reply was generated.','error');return;}showReplyOptions(items);replyStatus('Profile-aware reply drafts were generated locally. No email or profile data was sent to an AI service. Connect a secure backend in Settings for model-generated writing.','success');}
async function refineReply(kind){const text=$('replyBody').value.trim();if(!text){replyStatus('Write or generate a reply first.','error');return;}const p=await prefsGet();if(p.backendEndpoint&&p.externalAIConsent&&p.externalProfileConsent){try{const payload={schemaVersion:2,text,instruction:kind,style:tone,email:{sender:emailContext?.sender||'',subject:emailContext?.subject||'',text:emailContext?.text||'',conversationContext:emailContext?.conversationContext||''},profile:InboxActionProfile.professionalContextForAI(currentProfile),generationInstructions:['Revise the draft using the full email and thread context. Preserve the sender intention and original meaning.','Use only supported profile facts; do not invent facts, salary, availability, or commitments. Avoid placeholders and repeated information. Return a complete professional email for user review.']};const result=await remote('reply/refine',payload);if(!validReplyCandidate(result.text))throw Error('Backend returned an empty reply or a draft that failed local accuracy checks.');$('replyBody').value=withLocalProfileSignature(result.text).slice(0,5000);replyStatus('AI revision is ready. Profile context was sent only under your separate consent; review it before use.','success');}catch(error){replyStatus(error.message,'error');}return;}if(kind==='shorter'){$('replyBody').value=text.split(/\n\s*\n/).filter(Boolean).slice(0,3).join('\n\n');replyStatus('Removed later paragraphs locally. Review the shorter version.','success');}else if(kind==='detailed'){const extra=InboxActionProfile.generateReplies(emailContext,'detailed',currentProfile)[0]?.text;if(extra){$('replyBody').value=extra;replyStatus('Replaced with a fuller local reply using message context and relevant profile facts. Review before use.','success');}else replyStatus('Email context is unavailable for a detailed reply.','error');}else replyStatus(p.backendEndpoint&&p.externalAIConsent?'Enable separate AI profile consent in Settings to refine a profile-aware draft externally. Your draft was not sent.':'Grammar improvement requires a configured AI backend and separate profile consent. Your draft was not sent.','error');}
const PROFILE_FIELDS={profileName:'name',profilePhone:'phone',profileLocation:'location',profileEmail:'email',profileAlternativeEmail:'alternativeEmail',profilePreferredLocations:'preferredLocations',profileLinkedIn:'linkedIn',profileGitHub:'gitHub',profileEducation:'education',profileGraduation:'graduation',profileCgpa:'cgpa',profileCompany:'company',profileRole:'role',profileEmploymentStart:'employmentStart',profileEmploymentEnd:'employmentEnd',profileExperienceMonths:'experienceMonths',profileAchievements:'achievements',profileSkills:'skills',profileCertifications:'certifications',profileProjects:'projects',profileCareerInterests:'careerInterests'};
