async function saveReview(){const selected=[...$('suggestionList').querySelectorAll('.suggestion-check:checked')].map(x=>suggestions[Number(x.dataset.index)]).filter(Boolean);if(!selected.length){status('Select at least one action to save.',true);return;}const all=await tasksGet(),now=new Date().toISOString();let added=0,duplicates=0;for(const a of selected){const identity=a.messageId||a.threadId||a.emailSubject||'',signature=String(a.description||a.title).toLowerCase().replace(/\W+/g,' ').trim(),duplicate=all.some(t=>(t.messageId||t.threadId||t.emailSubject||'')===identity&&t.type===a.type&&String(t.description||t.title).toLowerCase().replace(/\W+/g,' ').trim()===signature);if(duplicate){duplicates++;continue;}all.unshift({...a,id:id(),status:a.direction==='sender'?'waiting':'pending',createdAt:now,completed:false,snoozedUntil:''});added++;}await tasksSet(all);$('reviewSection').hidden=true;suggestions=[];await refresh();status(added?`${added} task${added===1?'':'s'} saved${duplicates?`; ${duplicates} duplicate${duplicates===1?'':'s'} skipped`:''}.`:`${duplicates} duplicate suggestion${duplicates===1?' was':'s were'} skipped.`);}
