const INBOX_LABELS={urgent:'Urgent',important:'Important Personal','reply-required':'Reply required','pending-action':'Pending action',waiting:'Waiting for someone',informational:'Informational',promotional:'Promotional','job-opportunities':'Job Opportunity','interview-invitations':'Interview Invitation','hr-recruiter':'HR / Recruiter','application-updates':'Application Update',shortlisted:'Shortlisted',rejected:'Rejected',selected:'Selected','offer-letters':'Offer Letter','assessment-test':'Assessment / Test','followup-required':'Follow-up Required'};
function jobDetailsMarkup(details){const entries=Object.entries(details||{}).filter(([,value])=>value);return entries.length?'<p class="inbox-details">'+entries.map(([key,value])=>esc(key.replace(/[A-Z]/g,m=>' '+m).replace(/^./,m=>m.toUpperCase()))+': '+esc(value)).join(' ? ')+'</p>':'';}
async function renderInbox(){
 const saved=await chrome.storage.local.get({inboxAnalysis:null}),analysis=saved.inboxAnalysis;
 const items=Array.isArray(analysis?.emails)?analysis.emails.filter(Boolean).map(email=>({...email,classification:{category:'informational',priority:'low',confidence:0,why:'Legacy record; re-analyze this visible row for a current classification.',recommendation:'Review the visible email details.',...(email.classification||{})}})):[];
 inboxEmails=items;
 const byCategory=key=>items.filter(email=>email.classification.category===key).length;
 const jobCategories=['job-opportunities','application-updates','shortlisted','rejected','selected','offer-letters','assessment-test'];
 const counts={inboxTotal:items.length,inboxImportant:byCategory('important'),inboxUrgent:byCategory('urgent'),inboxReply:byCategory('reply-required'),inboxPending:byCategory('pending-action'),inboxWaiting:byCategory('waiting'),inboxCommitments:items.filter(email=>email.classification.commitment).length,inboxInformational:byCategory('informational'),inboxUnread:items.filter(email=>email.unread).length,inboxJobs:items.filter(email=>jobCategories.includes(email.classification.category)).length,inboxInterviews:byCategory('interview-invitations'),inboxHr:byCategory('hr-recruiter'),inboxPromotional:byCategory('promotional')};
 for(const [key,value] of Object.entries(counts)){const el=$(key);if(el)el.textContent=String(value);}
 const dashboardCounts={dashInboxCount:items.length,dashUnreadCount:counts.inboxUnread,dashJobCount:counts.inboxJobs,dashInterviewCount:counts.inboxInterviews,dashHrCount:counts.inboxHr,dashReplyCount:counts.inboxReply};
 for(const [key,value] of Object.entries(dashboardCounts)){const el=$(key);if(el)el.textContent=String(value);}
 $('inboxLastAnalyzed').textContent=analysis?.analyzedAt?`Last analyzed ${ago(analysis.analyzedAt)}`:'Not analyzed yet';
 const selectedCategory=$('inboxCategoryFilter').value,shown=items.map((email,index)=>({email,index})).filter(({email})=>selectedCategory==='all'||email.classification.category===selectedCategory);
 const card=({email,index})=>{const c=email.classification,url=safeGmailUrl(email.conversationUrl),label=INBOX_LABELS[c.category]||c.category;return `<article class="inbox-email-card"><details class="inbox-result-details"><summary><span class="inbox-category category-${esc(c.category)}">${esc(label)}</span><span class="inbox-confidence">${Math.round(Number(c.confidence)||0)}% confidence</span>${email.unread?'<span class="inbox-unread">Unread</span>':''}<strong>${esc(email.subject||'(No subject)')}</strong><span class="inbox-sender">${esc(email.sender||email.senderEmail||'Sender unavailable')}</span></summary><div class="inbox-email-main"><p class="inbox-sender">${email.senderEmail?esc(email.senderEmail)+' · ':''}${email.date?esc(email.date):''}${email.attachment?' · Attachment':''}</p><p class="inbox-snippet">${esc(email.snippet||'No preview text was available in the visible row.')}</p><p class="inbox-why">${esc(c.priority||'low').toUpperCase()} PRIORITY · ${esc(c.why||'No classification reason was returned.')}</p><p class="inbox-recommendation">Recommended action: ${esc(c.recommendation||'Review the visible email details.')}</p>${jobDetailsMarkup(c.jobDetails)}${email.labels?.length?`<p class="inbox-labels">Labels: ${esc(email.labels.join(', '))}</p>`:''}<div class="inbox-actions">${url?`<button class="button button-quiet inbox-open" type="button" data-index="${index}">Open conversation</button>`:''}${jobCategories.concat(['interview-invitations','hr-recruiter']).includes(c.category)?`<button class="button button-secondary inbox-track-application" type="button" data-index="${index}">Track application</button>`:''}${['urgent','important','reply-required','pending-action','waiting','followup-required',...jobCategories,'interview-invitations','hr-recruiter'].includes(c.category)?`<button class="button button-secondary inbox-create-task" type="button" data-index="${index}">Create task</button>`:''}<button class="icon-button inbox-feedback" type="button" data-index="${index}" data-feedback="up" aria-label="Classification was helpful">+</button><button class="icon-button inbox-feedback" type="button" data-index="${index}" data-feedback="down" aria-label="Classification was not helpful">-</button></div></div></details></article>`;};
 const rendered=shown.map(card).join(''),dashboardRendered=items.map((email,index)=>({email,index})).map(card).join('');
 $('inboxEmailList').innerHTML=rendered;$('dashboardInboxList').innerHTML=dashboardRendered;
 $('dashboardInboxEmpty').hidden=items.length>0;
 $('inboxAnalysisStatus').hidden=shown.length>0;
 $('inboxAnalysisStatus').textContent=!items.length?'No visible email results are available yet. Analyze the currently visible Gmail rows to populate this section.':shown.length===items.length?`Showing all ${items.length} analyzed visible email results. Categories are based on visible sender, subject and snippet.`:`No emails match this category filter. ${items.length} analyzed email results are available under All categories.`;
}async function loadInboxAnalysis(){const saved=await chrome.storage.local.get({inboxAnalysis:null});inboxEmails=saved.inboxAnalysis?.emails||[];await renderInbox();}
function readerErrorMessage(result){const message=typeof result?.error==='string'?result.error:JSON.stringify(result?.error||'Unknown Gmail reader error.');const diagnostic=result?.diagnostics?`\n\nGmail DOM diagnostics:\n${JSON.stringify(result.diagnostics,null,2)}`:'';return`${message}${diagnostic}`;}
async function analyzeVisibleInbox(){
 if(currentGmailMode!=='inbox'){await refreshGmailMode();if(currentGmailMode!=='inbox')return;}
 const prefs=await prefsGet();if(prefs.inboxAnalysisEnabled===false){status('Visible inbox analysis is disabled in Settings.',true);return;}
 const button=page==='inbox'?document.getElementById('refreshInboxAnalysis'):document.getElementById('analyzeVisibleInbox');
 analysisBusy=true;if(button){button.disabled=true;button.textContent='Analyzing visible rows…';}
 try{
  const tab=await targetTab();await chrome.scripting.executeScript({target:{tabId:tab.id},files:['content.js']});
  const result=await chrome.scripting.executeScript({target:{tabId:tab.id},func:()=>window.inboxToActionReader?.readVisibleInboxRows?.()||{error:'Gmail layout changed. Inbox analysis is temporarily unavailable.'}});
  const captured=result?.[0]?.result;if(captured?.error)throw Error(readerErrorMessage(captured));if(!captured||!Array.isArray(captured.rows))throw Error('Gmail layout changed. Inbox analysis is temporarily unavailable.');
  const preferences={vipSenders:String(prefs.vipSenders||'').split(',').map(x=>x.trim()).filter(Boolean),mutedSenders:String(prefs.mutedSenders||'').split(',').map(x=>x.trim()).filter(Boolean),feedback:prefs.inboxFeedback||{}};
  const rows=prefs.prioritizeUnread===false?captured.rows:[...captured.rows].sort((a,b)=>Number(!!b.unread)-Number(!!a.unread));
  status(rows.length?`Classifying ${rows.length} visible rows locally…`:'No visible Gmail rows were available to analyze.',!rows.length);
  const classified=await chrome.runtime.sendMessage({type:'CLASSIFY_VISIBLE_INBOX',emails:rows,preferences});
  if(!classified?.ok)throw Error(classified?.error||'Local inbox classification failed.');
  if(!Array.isArray(classified.classifications)||classified.classifications.length!==rows.length||classified.classifications.some(c=>!c||typeof c.category!=='string'))throw Error(`Analysis returned ${classified?.classifications?.length||0} classifications for ${rows.length} visible rows. No partial results were saved.`);
  const emails=rows.map((email,i)=>({...email,classification:classified.classifications[i],vip:!!classified.classifications[i].vip}));
  const analysis={emails,route:captured.route||'',tabId:tab.id,analyzedAt:new Date().toISOString()};
  await chrome.storage.local.set({inboxAnalysis:analysis});inboxEmails=emails;await renderInbox();
  if(emails.length)status(`Analyzed and displayed ${emails.length} visible email result${emails.length===1?'':'s'} locally.`);else status('No visible email rows were found. No analysis results were created.',true);
 }catch(error){document.getElementById('inboxAnalysisStatus').hidden=false;document.getElementById('inboxAnalysisStatus').textContent=error.message||'Inbox analysis failed.';status(error.message||'Inbox analysis failed.',true);}
 finally{analysisBusy=false;if(button){button.disabled=false;button.textContent=button.id==='refreshInboxAnalysis'?'Refresh Analysis':'Analyze Visible Inbox';}await refreshGmailMode();}
}
async function reclassifyInbox(){
 const prefs=await prefsGet(),preferences={vipSenders:String(prefs.vipSenders||'').split(',').map(x=>x.trim()).filter(Boolean),mutedSenders:String(prefs.mutedSenders||'').split(',').map(x=>x.trim()).filter(Boolean),feedback:prefs.inboxFeedback||{}};
 const result=await chrome.runtime.sendMessage({type:'CLASSIFY_VISIBLE_INBOX',emails:inboxEmails,preferences});
 if(!result?.ok||!Array.isArray(result.classifications)||result.classifications.length!==inboxEmails.length)throw Error(result?.error||'Could not reclassify the saved inbox results.');
 inboxEmails=inboxEmails.map((email,index)=>({...email,classification:result.classifications[index],vip:!!result.classifications[index].vip}));
 const saved=await chrome.storage.local.get({inboxAnalysis:null});if(saved.inboxAnalysis)await chrome.storage.local.set({inboxAnalysis:{...saved.inboxAnalysis,emails:inboxEmails}});await renderInbox();return true;
}
async function inboxAction(event){
 try{
  const button=event.target.closest('button');if(!button)return;
  const index=Number(button.dataset.index),email=Number.isInteger(index)?inboxEmails[index]:null;if(!email)return;
  if(button.classList.contains('inbox-open')){safeConversation(email.conversationUrl);return;}
  if(button.classList.contains('inbox-track-application')){await startApplicationFromEmail(email);return;}
  if(button.classList.contains('inbox-feedback')){
   const prefs=await prefsGet(),feedback={...(prefs.inboxFeedback||{})},key=`${String(email.senderEmail||email.sender||'').toLowerCase()}|${email.classification.category}`;
   feedback[key]=button.dataset.feedback;await prefsSet({inboxFeedback:feedback});
   const updated=await reclassifyInbox();if(updated)status('Local classification feedback saved. It adjusts confidence only; no model training occurs.');return;
  }
  if(button.classList.contains('inbox-create-task')){
   const title=`Review: ${email.subject||'Gmail message'}`,threadId=email.threadId||'',conversationUrl=safeGmailUrl(email.conversationUrl),all=await tasksGet();
   const duplicate=all.some(task=>task.source==='visible-inbox'&&(threadId?task.threadId===threadId:task.senderEmail===email.senderEmail&&task.emailSubject===email.subject));
   if(duplicate){status('A task from this visible conversation already exists.');return;}
   if(!confirm(`Create a local task for “${email.subject||'this email'}”?`))return;
   all.unshift({id:id(),title,description:email.snippet||email.classification.why||'Review the visible email result.',sender:email.sender||'',senderEmail:email.senderEmail||'',emailSubject:email.subject||'',dueDate:'',priority:email.classification.priority||'normal',type:'followup',direction:email.classification.category==='waiting'?'sender':'you',status:email.classification.category==='waiting'?'waiting':'pending',createdAt:new Date().toISOString(),completed:false,source:'visible-inbox',threadId,messageId:'',conversationUrl});
   await tasksSet(all);await refresh();status('Task created locally after confirmation.');
  }
 }catch(error){status(error.message||'Could not complete this inbox result action.',true);}
}
