async function startApplicationFromEmail(email){const apps=await applicationsGet(),threadId=email.threadId||'',url=safeGmailUrl(email.conversationUrl),existing=apps.find(a=>(threadId&&a.threadId===threadId)||(url&&a.conversationUrl===url));if(existing){go('career');status('This conversation is already in your Career Tracker.');return;}go('career');const form=$('applicationForm'),d=form.elements;form.reset();form.dataset.editId='';$('applicationFormTitle').textContent='Review application details';d.company.value=email.classification.jobDetails?.company||'';d.jobTitle.value=email.classification.jobDetails?.jobTitle||'';d.applicationDate.value='';d.status.value=statusForCareer(email.classification.category);d.interviewDate.value=email.classification.jobDetails?.interviewDate||'';d.followupDate.value='';d.notes.value=email.classification.recommendation||'';d.threadId.value=threadId;d.conversationUrl.value=url;form.hidden=false;form.scrollIntoView({behavior:'smooth',block:'start'});}
