$('connectBackend').addEventListener('click',async()=>{const raw=$('backendEndpoint').value.trim();let u;try{u=new URL(raw);if(u.username||u.password||u.search||u.hash||u.pathname!=='/')throw Error('Enter a base origin only, without credentials, path, query, or fragment.');if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw Error('Use HTTPS. HTTP is allowed for localhost testing only.');}catch(error){status(error.message||'Enter a valid backend URL.',true);return;}const origin=`${u.origin}/*`;try{const granted=await chrome.permissions.request({origins:[origin]});if(!granted){status('Chrome did not grant backend access. Local processing remains available.',true);return;}await prefsSet({backendEndpoint:u.origin});await chrome.storage.session.set({backendAccessToken:$('backendToken').value.trim()});$('backendToken').value='';await updateBackendStatus();status('Backend origin permission saved. External AI is still disabled until you enable consent.');}catch(error){status(`Could not connect backend: ${error.message}`,true);}});
